# Execute the analyzers on the current demo/template data to produce concrete outputs now.
import subprocess, json, os, textwrap, sys, pandas as pd

base = "/mnt/data"

def run_py(path):
    try:
        out = subprocess.run(["python", path], capture_output=True, text=True, check=False)
        return {"code": out.returncode, "stdout": out.stdout, "stderr": out.stderr}
    except Exception as e:
        return {"code": -1, "stdout": "", "stderr": str(e)}

results = {}

# 1) Kappa (theta4)
results["theta4"] = run_py(os.path.join(base, "analyze_theta4_kappa.py"))

# 2) Epsilon (GW)
results["gw"] = run_py(os.path.join(base, "analyze_gw_epsilon.py"))

# 3) Sigma (K-map masses)
results["kmap"] = run_py(os.path.join(base, "analyze_kmap_sigma.py"))

# 4) Width floor (will likely note insufficient data since widths are NaN in template)
results["width"] = run_py(os.path.join(base, "analyze_width_floor.py"))

results

